#' Project matrix onto a permutation-invariant space
#'
#' Project `S` onto the space of symmetric matrices invariant under the
#' cyclic group generated by `perm`. Entries that must be equal under
#' this symmetry are replaced by their average.
#'
#' The permutation can be specified in advance or selected using [find_MAP()].
#' Model selection by MAP concerns the cyclic group; the subsequent projection
#' estimates the covariance matrix within the selected model.
#'
#' The projection implements
#' [Definition 3 from references](https://arxiv.org/abs/2004.03503).
#'
#' @section Covariance estimation:
#' Let `Z` contain `n` observations in rows. The function returns the projection
#' of the supplied `S` without changing its normalization:
#' * If the mean is known to be zero and `S = crossprod(Z) / n`, the projection
#'   is the covariance MLE in the specified symmetry model, when that MLE exists.
#' * If `S = cov(Z)`, the projection retains the denominator `n - 1` used by
#'   [stats::cov()]. For the full Gaussian likelihood maximized over both an
#'   unrestricted mean and a covariance matrix with the specified symmetry,
#'   the covariance MLE would be `(n - 1) / n * project_matrix(S, perm)`, when it exists.
#'
#' For `S = cov(Z)` with `was_mean_estimated = TRUE`, `gips` uses the projection
#' without this rescaling, and [logLik.gips()] uses `n - 1` in its likelihood
#' calculation. This is the package's convention based on centered data,
#' distinct from the full Gaussian likelihood described above. See the
#' **Estimated mean** subsection in `vignette("Theory", package = "gips")`.
#'
#' @section MLE availability:
#' `project_matrix()` does not receive the sample size and does not check
#' whether an MLE is available. It can return a singular projected matrix.
#' For a corresponding `gips` object `g`, [summary.gips()] reports the
#' sample-size threshold in `summary(g)$n0`. The field `summary(g)$MLE_available`
#' combines the sample-size check with a numerical positive-definiteness check
#' of the projection, using the package's convention described above.
#'
#' @param S A square empirical covariance matrix to be projected.
#'     (See the `S` parameter in the `gips()` function).
#'     For optional multi-sample use, `S` can be a list of covariance matrices;
#'     see the **Multi-sample** section below.
#'     When it is not positive semi-definite,
#'     it shows a warning of a class `not_positive_semi_definite_matrix`.
#' @param perm A permutation to be projected on.
#'     An object of a `gips` class,
#'     a `gips_perm` class, or anything that can be used
#'     as the `x` argument in the `gips_perm()` function.
#' @param precomputed_equal_indices This parameter is no longer used and will be deleted in v1.4.0.
#'
#' @section Multi-sample:
#' When `S` is a list of matrices (as stored in a multi-sample `gips` object),
#' `project_matrix()` applies the same permutation projection to each element
#' and returns a list of projected matrices of the same length.
#'
#' @returns The matrix `S` projected on the space of symmetric matrices invariant
#' by a cyclic group generated by `perm`. See **Covariance estimation** for
#' its statistical interpretation.
#'
#' When `S` is a list, returns a list of projected matrices.
#' @export
#'
#' @seealso
#' * [Wikipedia - Estimation of covariance matrices](https://en.wikipedia.org/wiki/Estimation_of_covariance_matrices)
#' * **Project Matrix - Equation (6)** section of
#'     `vignette("Theory", package = "gips")` or its
#'     [pkgdown page](https://przechoj.github.io/gips/articles/Theory.html) -
#'     A place to learn more about the math
#'     behind the `gips` package and see
#'     more examples of `project_matrix()`.
#' * [find_MAP()] - Searches for a cyclic group with maximum posterior weight.
#'     Heuristic optimizers do not guarantee finding the maximum.
#'     The returned permutation can be used to project `S` onto the selected
#'     symmetry model (see examples).
#' * [gips_perm()] - Constructor for the `perm` parameter.
#' * [plot.gips()] - For `plot(g, type = "MLE")`,
#'     the `project_matrix()` is called (see examples).
#' * [summary.gips()] - Reports `n0` and `MLE_available` for a `gips` object;
#'     see the **MLE availability** section.
#'
#' @examples
#' p <- 6
#' my_perm <- "(14)(23)" # permutation (1,4)(2,3)(5)(6)
#' number_of_observations <- 10
#' X <- matrix(rnorm(p * number_of_observations), number_of_observations, p)
#' S <- cov(X)
#' projected_S <- project_matrix(S, perm = my_perm)
#' projected_S
#' # The value in [1,1] is the same as in [4,4]; also, [2,2] and [3,3];
#'   # also [1,2] and [3,4]; also, [1,5] and [4,5]; and so on
#'
#' # Plot the projected matrix:
#' g <- gips(S, number_of_observations, perm = my_perm)
#' plot(g, type = "MLE")
#'
#' # Search for the MAP symmetry group:
#' g_MAP <- find_MAP(g, max_iter = 10, show_progress_bar = FALSE, optimizer = "Metropolis_Hastings")
#' # Then, project S onto the selected model:
#' S_MAP <- project_matrix(attr(g, "S"), perm = g_MAP)
#' S_MAP
#' plot(g_MAP, type = "heatmap")
project_matrix <- function(S, perm, precomputed_equal_indices = NULL) {
  # Multi-sample: project each group's matrix and return a list
  if (is.list(S)) {
    return(lapply(S, function(S_g) project_matrix(S_g, perm)))
  }
  if (!is.matrix(S)) {
    rlang::abort(c("There was a problem identified with the provided arguments:",
      "i" = "`S` must be a matrix.",
      "x" = paste0(
        "You provided `S` with `class(S) == (",
        paste(class(S), collapse = ", "),
        ")`."
      )
    ))
  }
  if (nrow(S) != ncol(S)) {
    rlang::abort(c("There was a problem identified with the provided arguments:",
      "i" = "`S` must be a square matrix.",
      "x" = paste0(
        "You provided `S` as a matrix, but with different sizes: ",
        nrow(S), " and ", ncol(S), "."
      )
    ))
  }
  if (!is.positive.semi.definite.matrix(S)) {
    rlang::warn(c(
      "i" = "`project_matrix()` is designed for positive semi-definite matrices",
      "x" = "You provided `S` that is not positive semi-definite matrix",
      "*" = "`gips` can still project this matrix on the provided permutation",
      "i" = "Did you provide the wrong `S` matrix?"
    ), class = "not_positive_semi_definite_matrix")
  }

  perm_size <- ncol(S)
  if (!inherits(perm, "gips_perm")) {
    perm <- gips_perm(perm, perm_size)
  }
  validate_gips_perm(perm)
  if (attr(perm, "size") != ncol(S)) {
    rlang::abort(c("There was a problem identified with the provided arguments:",
      "i" = "Size of `perm` must be equal to number of columns and rows of `S`.",
      "x" = paste0(
        "You provided `perm` with `size == ",
        attr(perm, "size"),
        "`, but the `S` matrix has ",
        ncol(S), " columns."
      )
    ))
  }

  project_matrix_cpp_(S, perm)
}

#' @noRd
project_matrix_cpp_ <- function(S, perm) {
  project_matrices_cpp_(list(S), perm)[[1]]
}

#' @noRd
project_matrices_cpp_ <- function(matrices, perm) {
  projected_matrices <- project_matrices_cpp_impl_(matrices, perm_to_sigma_(perm))
  names(projected_matrices) <- names(matrices)

  for (i in seq_along(projected_matrices)) {
    colnames(projected_matrices[[i]]) <- colnames(matrices[[i]])
    rownames(projected_matrices[[i]]) <- rownames(matrices[[i]])
  }

  projected_matrices
}

#' Convert a `gips_perm` object to a 1-based permutation vector
#'
#' @noRd
perm_to_sigma_ <- function(perm) {
  sigma <- seq_len(attr(perm, "size"))

  for (cycle in perm) {
    sigma[cycle] <- c(cycle[-1], cycle[1])
  }

  sigma
}
